// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(bytes4 selector) public {
        bytes4 accessControlId = type(IAccessControlIdHack).interfaceId;
        bytes4 erc165Id = type(IERC165IdHack).interfaceId;

        bool okAccess = c.supportsInterface(accessControlId);
        bool okErc165 = c.supportsInterface(erc165Id);

        // also exercise a fuzzed selector through the public surface
        bool okFuzzed = c.supportsInterface(selector);

        assertTrue(
            (okAccess == true) && (okErc165 == true) &&
            (okFuzzed == (selector == accessControlId || selector == erc165Id)),
            "supportsInterface must advertise IAccessControl and IERC165"
        );
    }
}

interface IAccessControlIdHack {
    function hasRole(bytes32 role, address account) external view returns (bool);
    function getRoleAdmin(bytes32 role) external view returns (bytes32);
    function grantRole(bytes32 role, address account) external;
    function revokeRole(bytes32 role, address account) external;
    function renounceRole(bytes32 role, address account) external;
}

interface IERC165IdHack {
    function supportsInterface(bytes4 interfaceId) external view returns (bool);
}
